BOOL ReadScopeList(wStream* s, SCOPE_LIST* scopeList)
{
    UINT32 scopeCount;
    size_t i;

    if (!Stream_EnsureRemaining(s, 4))
        return FALSE;

    Stream_Read_UINT32(s, scopeCount);

    scopeList->scopeCount = scopeCount;
    scopeList->scopes = (LICENSE_BLOB*)malloc(scopeCount * sizeof(LICENSE_BLOB));
    if (!scopeList->scopes)
        return FALSE;

    for (i = 0; i < scopeCount; i++)
    {
        if (!Stream_EnsureRemaining(s, sizeof(LICENSE_BLOB)))
        {
            free(scopeList->scopes);
            scopeList->scopes = NULL;
            return FALSE;
        }

        Stream_Read(s, &(scopeList->scopes[i]), sizeof(LICENSE_BLOB));
    }

    return TRUE;
}

